-- schema_v13_govt_buses.sql
-- Run ONCE in Supabase > SQL Editor, AFTER schema_v12_places.sql.
-- Imports every bus from BUS_TIMING_DETAILS.xlsx (all 7 sheets) and the 3 timetable pictures.
--   * Vedaranyam stand      : FULL SHEET + poster (Nagapattinam, Kodiyakkarai, Kariyapattinam extras)
--   * Thanikkottagam        : VDM-TTP, TTP-VDM sheets
--   * Thulasiyapattinam     : VDM-PKT, PKT-VDM, VP (PKT,VDM), VP (TTP,VDM) sheets (duplicates merged)
--   * Thiruthuraipoondi stand: pictures 2 & 3 (to Vedaranyam via Vaimedu / via Kariyapattinam)
-- Names follow your format: name = English (Ganesa bus, Government express bus), bus_no = Tamil name; route number is added at the end.
-- TNSTC buses = 'Government'. Buses that the Excel itself marks PRIVATE = 'Private'.
-- Safe to run again: nothing is added twice.

-- OPTIONAL: to start clean, remove the old buses first (this also deletes their timings). Remove the two dashes to use it.
-- delete from buses;

drop table if exists _imp;
create table _imp (
  place text, mins int, bus_no text, operator text, svc text, btype text,
  name text, from_place text, to_place text, via text, notes text
);


-- 1) buses (one row per bus service)
select distinct on (i.name, i.operator, i.from_place, i.to_place, coalesce(i.via,''))
       i.name, i.bus_no, i.operator, i.svc, i.btype, i.from_place, i.to_place, i.via, i.notes, true
from _imp i
where not exists (
  select 1 from buses b
  where b.name = i.name
    and coalesce(b.operator,'') = coalesce(i.operator,'')
    and b.from_place = i.from_place and b.to_place = i.to_place
    and coalesce(b.via,'') = coalesce(i.via,'')
);

-- 2) timings (bus + place + time)
select distinct b.id, p.id, make_time(i.mins / 60, i.mins % 60, 0), 'Daily'
from _imp i
join places p on lower(p.name) = lower(i.place)
join buses  b on b.name = i.name
             and coalesce(b.operator,'') = coalesce(i.operator,'')
             and b.from_place = i.from_place and b.to_place = i.to_place
             and coalesce(b.via,'') = coalesce(i.via,'')
where not exists (
  select 1 from timings t
  where t.bus_id = b.id and t.place_id = p.id and t.departure_time = make_time(i.mins / 60, i.mins % 60, 0)
);

drop table _imp;

-- OPTIONAL: if you want EVERY bus (including the ones the Excel marks PRIVATE) shown as Government, run this line:
-- update buses set bus_type = 'Government';

notify pgrst, 'reload schema';

